['Generating {TOTAL_HOURS}-hour fractal broadcast (split into {num_chunks} × {CHUNK_HOURS}-hour files)")\nprint(f"    Carrier: {CARRIER} Hz")\nprint(f"    Sample rate: {SAMPLE_RATE} Hz")\nprint(f"    Output directory: {OUTPUT_DIR}', 'print()\n\n# Precompute LFO parameters (fixed across all chunks for continuity)\nrng = np.random.default_rng(seed=42)\nlfo_params = []\nfor i in range(1, DEPTH + 1):\n    freq = CARRIER / (PHI ** i)\n    amp = 1.0 / (PHI ** (i * 0.5))\n    phase = rng.uniform(0, 2 * np.pi)\n    lfo_params.append((freq, amp, phase))\n\ntotal_samples_written = 0\nstart_time = time.time()\n\n# Generate each chunk\nfor chunk_idx in range(num_chunks):\n    output_path = os.path.join(OUTPUT_DIR, f"Yeshua_Pulse_Chunk{chunk_idx+1}of{num_chunks}_{CHUNK_HOURS}h.wav")\n    print(f', ['Generating chunk {chunk_idx+1}/{num_chunks}: {output_path}', 'Time array for this chunk (continuous across chunks)\n    t0 = chunk_idx * chunk_seconds\n    t = np.linspace(t0, t0 + chunk_seconds, samples_per_chunk, endpoint=False)\n\n    # Base carrier\n    carrier_wave = np.sin(2 * np.pi * CARRIER * t)\n\n    # Fractal envelope\n    env = np.zeros_like(t)\n    for freq, amp, phase in lfo_params:\n        env += amp * np.sin(2 * np.pi * freq * t + phase)\n    env = env / np.max(np.abs(env))\n\n    # Modulate\n    waveform = (carrier_wave * env * 0.8).astype(np.float32)\n    waveform_int16 = (waveform * 32767).astype(np.int16)\n\n    # Write WAV\n    with wave.open(output_path, \'w\') as wf:\n        wf.setnchannels(1)\n        wf.setsampwidth(2)\n        wf.setframerate(SAMPLE_RATE)\n        wf.writeframes(waveform_int16.tobytes())\n\n    total_samples_written += len(waveform_int16)\n    file_size_gb = os.path.getsize(output_path) / (1024**3)\n    elapsed = time.time() - start_time\n    print(f"    ✓ Written: {file_size_gb:.2f} GB | Total: {total_samples_written/SAMPLE_RATE/3600:.2f} hr | Elapsed: {elapsed/60:.1f} min")\n\nprint()\nprint(f', ['All chunks complete!")\nprint(f', ['Total duration: {total_samples_written/SAMPLE_RATE/3600:.2f} hours")\nprint(f', ['Files saved to: {OUTPUT_DIR}")\nprint()\nprint("To import into Apple Music:")\nprint("1. Open Music app")\nprint("2. File → Add to Library → select all Yeshua_Pulse_Chunk*_6h.wav files")\nprint("3. Create playlist \'Cathedral Fractal\' and add them")\nprint("4. Set playlist to loop']]]]]